window.VF1_UNITS = {"2":{"unit":2,"code":"VF1-U02","title":"Learning & Doing","startNumber":26,"endNumber":54,"entries":[{"number":26,"term":"achieve · achievement","sourceTerm":"achieve (v) · achievement (n)","spoken":"achieve · achievement","ipa":"/əˈtʃiːv əˈtʃiːvmənt/","type":"verb · noun","meaning":"đạt được, hoàn thành · thành tựu, sự đạt được","definition":"To reach a goal successfully; something successfully completed.","note":"","example":"Lan worked hard to achieve her goal, and this achievement made her proud."},{"number":27,"term":"concentrate on ~ focus on","sourceTerm":"concentrate on ~ focus on","spoken":"concentrate on ~ focus on","ipa":"/ˈkɑːnsəˌntreɪt ɑːn ˈfoʊkəs ɑːn/","type":"phrase / pattern","meaning":"tập trung vào","definition":"To give all your attention to something.","note":"concentrate on nhấn mạnh nỗ lực tinh thần; focus on nhấn mạnh hướng sự chú ý vào một điểm.","example":"Please concentrate on the text and focus on its main idea."},{"number":28,"term":"consider","sourceTerm":"consider (v)","spoken":"consider","ipa":"/kəˈnsɪdɚ/","type":"verb","meaning":"cân nhắc… · coi…","definition":"To think carefully about something; to regard someone or something as.","note":"","example":"Before joining the course, Minh considered the cost and study time."},{"number":29,"term":"course","sourceTerm":"course (n)","spoken":"course","ipa":"/kɔːrs/","type":"noun","meaning":"khóa học","definition":"A series of lessons in a particular subject.","note":"","example":"This English course helps students speak and write more clearly."},{"number":30,"term":"degree","sourceTerm":"degree (n)","spoken":"degree","ipa":"/dɪˈɡriː/","type":"noun","meaning":"bằng đại học","definition":"A qualification awarded by a university.","note":"","example":"After getting her degree, Mai hopes to teach English."},{"number":31,"term":"expert · expertise","sourceTerm":"expert (n) · expertise (n)","spoken":"expert · expertise","ipa":"/ˈɛkspɚt ˌɛkspɚˈtiːz/","type":"noun","meaning":"chuyên gia · kiến thức, kĩ năng chuyên môn","definition":"A person with specialist knowledge; specialist knowledge or skill.","note":"","example":"The expert shared her expertise through a short, clear lesson."},{"number":32,"term":"fail to do st >< succeed in doing st","sourceTerm":"fail to do st >< succeed in doing st","spoken":"fail to do something >< succeed in doing something","ipa":"/feɪl tuː duː ˈsʌmθɪŋ səˈksiːd ɪn ˈduːɪŋ ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"không làm được / thất bại khi làm việc gì · thành công trong việc làm gì","definition":"Not to achieve something; to achieve a desired result.","note":"Chú ý cặp đối lập hoặc điểm khác nhau được đánh dấu trong danh sách. Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: fail to do st >< succeed in doing st","example":"If you fail to answer one question, keep trying; you can still succeed in completing the test."},{"number":33,"term":"hesitate + to do st","sourceTerm":"hesitate (v) + to do st","spoken":"hesitate to do something","ipa":"/ˈhɛzəˌteɪt tuː duː ˈsʌmθɪŋ/","type":"verb","meaning":"chần chừ, do dự","definition":"To pause because you are uncertain or unwilling.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: hesitate (v) + to do st","example":"Do not hesitate to ask your teacher when you need help."},{"number":34,"term":"make progress","sourceTerm":"make progress","spoken":"make progress","ipa":"/meɪk ˈprɑːˌɡrɛs/","type":"word / phrase","meaning":"tiến bộ","definition":"To improve or move closer to a goal.","note":"","example":"Reading every day helps students make progress in English."},{"number":35,"term":"mental · physical","sourceTerm":"mental (a) · physical (a)","spoken":"mental · physical","ipa":"/ˈmɛntəl ˈfɪzɪkəl/","type":"adjective","meaning":"thuộc tinh thần hoặc trí óc · thuộc thể chất hoặc cơ thể","definition":"Related to the mind; related to the body.","note":"","example":"Regular exercise supports physical health, while enough sleep supports mental health."},{"number":36,"term":"qualification","sourceTerm":"qualification (n)","spoken":"qualification","ipa":"/ˌkwɑːləfəˈkeɪʃən/","type":"noun","meaning":"trình độ chuyên môn","definition":"An official record of education, training, or skills.","note":"","example":"This teaching job needs a qualification and good English."},{"number":37,"term":"remind sb to do st · remind sb of st","sourceTerm":"remind sb to do st · remind sb of st","spoken":"remind somebody to do something · remind somebody of something","ipa":"/riˈmaɪnd ˈsʌˌmbɑːdi tuː duː ˈsʌmθɪŋ riˈmaɪnd ˈsʌˌmbɑːdi ʌv ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"nhắc ai làm gì · làm ai nhớ đến người hoặc điều gì","definition":"To help someone remember an action or fact.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: remind sb to do st · remind sb of st","example":"The teacher reminded us to bring our books and reminded us of tomorrow's test."},{"number":38,"term":"revise · revision","sourceTerm":"revise (v) · revision (n)","spoken":"revise · revision","ipa":"/rɪˈvaɪz riˈvɪʒən/","type":"verb · noun","meaning":"ôn tập, sửa đổi · sự ôn tập, bản sửa đổi","definition":"To study something again; the process of reviewing.","note":"","example":"I revise new words every evening, and my weekly revision helps me remember them."},{"number":39,"term":"be capable of V-ing ~ be able to V","sourceTerm":"be capable of V-ing ~ be able to V","spoken":"be capable of doing ~ be able to verb","ipa":"/biː ˈkeɪpəbəl ʌv ˈduːɪŋ biː ˈeɪbəl tuː vɝːb/","type":"phrase / pattern","meaning":"có thể, có khả năng làm gì","definition":"To have the ability to do something.","note":"capable of + V-ing; able to + V. Capable còn gợi khả năng/năng lực nói chung.","example":"With regular practice, most students are capable of speaking more clearly and are able to correct their mistakes."},{"number":40,"term":"learn st by heart","sourceTerm":"learn st by heart","spoken":"learn something by heart","ipa":"/lɝːn ˈsʌmθɪŋ baɪ hɑːrt/","type":"phrase / pattern","meaning":"học thuộc lòng","definition":"To memorize something exactly.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: learn st by heart","example":"Do not just learn the sentence by heart; try to understand it too."},{"number":41,"term":"for instance ~ for example","sourceTerm":"for instance ~ for example","spoken":"for instance ~ for example","ipa":"/fɔːr ˈɪnstəns fɔːr ɪˈɡzæmpəl/","type":"phrase / pattern","meaning":"chẳng hạn · ví dụ","definition":"A phrase used to introduce an example.","note":"for instance và for example cùng nêu ví dụ; for instance hơi trang trọng hơn.","example":"Students can revise in several ways. For instance, they can make word cards; for example, each card can show one word and its meaning."},{"number":42,"term":"conclude · in conclusion","sourceTerm":"conclude (v) · in conclusion","spoken":"conclude · in conclusion","ipa":"/kəˈnkluːd ɪn kəˈnkluːʒən/","type":"verb","meaning":"kết luận · tóm lại, kết luận lại","definition":"To reach a final opinion; used to introduce a final point.","note":"","example":"The report concludes that daily practice helps. In conclusion, students should practise a little every day."},{"number":43,"term":"in favor of","sourceTerm":"in favor of","spoken":"in favor of","ipa":"/ɪn ˈfeɪvɚ ʌv/","type":"phrase / pattern","meaning":"đồng tình, ủng hộ","definition":"Supporting or agreeing with something.","note":"","example":"Most students are in favor of having a quiet place to read."},{"number":44,"term":"in general >< in particular","sourceTerm":"in general >< in particular","spoken":"in general >< in particular","ipa":"/ɪn ˈdʒɛnɚəl ɪn pɚˈtɪkjəlɚ/","type":"phrase / pattern","meaning":"nói chung · nói riêng, cụ thể là","definition":"Usually or as a whole; specifically or especially.","note":"in general nghĩa là xét tổng thể; in particular nghĩa là riêng một người/vật/điểm cụ thể.","example":"In general, the class enjoys English; Linh, in particular, enjoys reading."},{"number":45,"term":"brave · bravery","sourceTerm":"brave (a) · bravery (n)","spoken":"brave · bravery","ipa":"/breɪv ˈbreɪvɚi/","type":"noun · adjective","meaning":"dũng cảm · lòng dũng cảm","definition":"Showing courage; the quality of being courageous.","note":"","example":"Nam was brave enough to speak first, and his bravery helped the group feel calm."},{"number":46,"term":"instruct sb to do st · instructor · instruction","sourceTerm":"instruct (v) sb to do st · instructor (n) · instruction (n)","spoken":"instruct somebody to do something · instructor · instruction","ipa":"/ˌɪˈnstrʌkt ˈsʌˌmbɑːdi tuː duː ˈsʌmθɪŋ ˌɪˈnstrʌktɚ ˌɪˈnstrʌkʃən/","type":"verb · noun","meaning":"hướng dẫn, chỉ dẫn ai làm gì · người hướng dẫn · lời chỉ dẫn, hướng dẫn","definition":"To teach or direct; a teacher or trainer; directions.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: instruct (v) sb to do st · instructor (n) · instruction (n)","example":"The instructor instructed us to read the instructions before the activity."},{"number":47,"term":"memory · memorize · memorial","sourceTerm":"memory (n) · memorize (v) · memorial (n)","spoken":"memory · memorize · memorial","ipa":"/ˈmɛmɚi ˈmɛmɚˌaɪz məˈmɔːriəl/","type":"verb · noun","meaning":"trí nhớ, kí ức · ghi nhớ · đài hoặc vật tưởng niệm","definition":"The ability to remember; to learn and remember; a structure that honours someone.","note":"","example":"We visited a memorial, memorized its name, and later described it from memory."},{"number":48,"term":"refer to sb/st · reference · reference book","sourceTerm":"refer to sb/st · reference (n) · reference book","spoken":"refer to somebody or something · reference · reference book","ipa":"/rəˈfɝː tuː ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ ˈrɛfɚəns ˈrɛfɚəns bʊk/","type":"noun","meaning":"đề cập đến, tham khảo · sự tham khảo, tài liệu dẫn · sách tham khảo","definition":"To mention something; a source of information; a book used for information.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: refer to sb/st · reference (n) · reference book","example":"When you write your answer, refer to the reference book and give the page as a reference."},{"number":49,"term":"simple · simplify · simplicity","sourceTerm":"simple (a) · simplify (v) · simplicity (n)","spoken":"simple · simplify · simplicity","ipa":"/ˈsɪmpəl ˈsɪmpləˌfaɪ sɪˈmplɪsəti/","type":"verb · noun · adjective","meaning":"đơn giản · đơn giản hóa · sự đơn giản","definition":"Easy to understand; to make easier; the quality of being simple.","note":"","example":"The teacher simplified the task and gave a simple example; its simplicity helped everyone understand."},{"number":50,"term":"educate · education","sourceTerm":"educate (v) · education (n)","spoken":"educate · education","ipa":"/ˈɛdʒəˌkeɪt ˌɛdʒəˈkeɪʃən/","type":"verb · noun","meaning":"giáo dục · sự hoặc nền giáo dục","definition":"To teach and develop knowledge; the process of teaching and learning.","note":"","example":"Schools educate young people, but education also happens at home."},{"number":51,"term":"cope with ~ deal with","sourceTerm":"cope with ~ deal with","spoken":"cope with ~ deal with","ipa":"/koʊp wɪð diːl wɪð/","type":"phrase / pattern","meaning":"đối phó, xử lí","definition":"To manage a difficult situation.","note":"cope with thường nói đến xoay xở với khó khăn; deal with rộng hơn: xử lý một vấn đề/tình huống.","example":"A clear study plan helps students cope with a lot of work and deal with hard tasks."},{"number":52,"term":"look up","sourceTerm":"look up","spoken":"look up","ipa":"/lʊk ʌp/","type":"phrasal verb","meaning":"tra cứu","definition":"To search for information in a reference source.","note":"","example":"If you do not know a word, look it up in a dictionary."},{"number":53,"term":"cross out","sourceTerm":"cross out","spoken":"cross out","ipa":"/krɔːs aʊt/","type":"phrasal verb","meaning":"gạch bỏ","definition":"To draw a line through something that is wrong.","note":"","example":"Cross out the wrong word and write the correct one."},{"number":54,"term":"read out","sourceTerm":"read (v) out","spoken":"read out","ipa":"/riːd aʊt/","type":"phrasal verb","meaning":"đọc to thành tiếng","definition":"To say the words of a written text aloud.","note":"","example":"Please read the final paragraph out so the whole class can hear it."}],"pronunciationFocus":[{"entryNumber":31,"points":[{"category":"word-stress","note":"expert nhấn âm đầu; expertise nhấn âm tiết cuối /ˈtiːz/"}]},{"entryNumber":36,"points":[{"category":"word-stress","note":"qualification nhấn vào /ˈkeɪ/ ngay trước phần /ʃən/"}]},{"entryNumber":38,"points":[{"category":"common-error","note":"revise kết thúc bằng /z/, còn revision có âm /ʒ/"},{"category":"final-sound","note":"Giữ /z/ ở cuối revise; không đổi thành /s/"}]},{"entryNumber":46,"points":[{"category":"word-stress","note":"instruct và instruction cùng nhấn vào phần /ˈstrʌk/"},{"category":"final-sound","note":"instruct kết thúc bằng /kt/; trong instruction, phần cuối chuyển thành /kʃən/"}]},{"entryNumber":49,"points":[{"category":"word-stress","note":"simple và simplify nhấn âm đầu; simplicity chuyển trọng âm sang âm tiết thứ hai"}]},{"entryNumber":53,"points":[{"category":"linking","note":"Trong cross‿out, nối /s/ cuối cross sang nguyên âm /aʊ/ của out"}]},{"entryNumber":54,"points":[{"category":"common-error","note":"read trong read out là dạng nguyên mẫu /riːd/, không đọc như dạng quá khứ /rɛd/"},{"category":"linking","note":"Trong read‿out, nối /d/ cuối read sang nguyên âm /aʊ/ của out"}]}]}};
